design.css:
/* Onyx — the Nuvio look: near-black, white on black, stadium buttons. Phone values follow Nuvio
   Mobile 0.5.5 (docs/theme-references/nuvio-phone-parity.md); desktop keeps its own block below. */

/* Home has no app bar of its own: the featured banner fills the top of the screen and the header floats over it. */
[data-slot="home.header"] { position: absolute; inset: 0 0 auto; z-index: 5; background: linear-gradient(to bottom, rgba(13, 13, 13, 0.45), rgba(13, 13, 13, 0)); }
[data-slot="home.hero"] { border-radius: 0 0 28px 28px; overflow: hidden; }
[data-part="onyx.hero"] > [data-part="onyx.info"] { z-index: 2; }
[data-part="onyx.details"] { padding: 0 28px; }
/* Slide markers are drawn on the marker's track; the button around it keeps its hit area unpainted. */
[data-part="hero.dot.track"] { width: 8px !important; height: 8px !important; border-radius: 999px !important; background: rgba(245, 247, 248, 0.35) !important; transition: width 220ms cubic-bezier(0.2, 0, 0, 1), background-color 220ms cubic-bezier(0.2, 0, 0, 1); }
[data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 32px !important; background: rgba(245, 247, 248, 0.92) !important; }

/* ── Desktop Home ── */
@media (min-width: 641px) {
  [data-part="onyx.hero"]::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    background: linear-gradient(to bottom, rgba(13, 13, 13, 0) 0%, rgba(13, 13, 13, 0.04) 16%, rgba(13, 13, 13, 0.14) 32%, rgba(13, 13, 13, 0.34) 50%, rgba(13, 13, 13, 0.6) 68%, rgba(13, 13, 13, 0.86) 84%, #0d0d0d 100%) !important;
    pointer-events: none;
  }
  [data-part="onyx.logo"] img { max-height: 92px; object-fit: contain; }
  [data-part="row.title"], [data-part="block.title"] { font-size: 20px; font-weight: 700; color: #f5f7f8; }
}

/* ── Phone Home and shell: Nuvio Mobile (HomeScreen.kt, HomeHeroSection.kt, ShelfComponents.kt,
   HomeContinueWatchingSection.kt, FloatingNavigationBar.android.kt). The root is 16 px
   (`mobile.rootSize`), so 1 px here is 1 dp there. Single-line text in Nuvio's own type roles is
   trimmed to 1.17 x its size (no leading above or below); Material-default roles keep theirs. ── */
@media (max-width: 640px) {
  /* Featured banner: full bleed under the status bar, 1.16 x the width tall (82 % of the screen at
     most); with Continue Watching it leaves that whole row above the bottom bar. */
  [data-slot="home.hero"] { margin-top: calc(-1 * env(safe-area-inset-top, 0px)) !important; }
  /* The header floats over the banner, but the izumi mark keeps clear of the status bar: it starts
     12 px under the inset, and the header's scrim runs on up behind the status bar. */
  [data-slot="home.header"] { padding-top: calc(env(safe-area-inset-top, 0px) + 12px) !important; }
  [data-slot="home.hero"][data-variant="template"] { height: clamp(360px, min(82svh, 116vw), 760px) !important; min-height: 0 !important; max-height: none !important; margin-bottom: 12px !important; }
  [data-slot="home"]:has([data-row][data-role="continue"]) [data-slot="home.hero"][data-variant="template"] { height: clamp(360px, min(82svh, calc(100svh - 297.8px - env(safe-area-inset-bottom, 0px))), 760px) !important; }
  /* Art 1.14 x the banner, centred (sized rather than transformed, so it stays in the fade's layer).
     It stops 2 px short of the banner's bottom: the art and the fade over it are clipped on the same
     part-covered device pixel there, which let a light line of art through. The fade is solid
     #0D0D0D at the bottom, so nothing of the art is lost. (7 / 114 of the art overhangs the banner.) */
  [data-part="onyx.hero-art"] { inset: -7% !important; width: 114% !important; height: 114% !important; clip-path: inset(0 0 calc(6.1404% + 2px) 0); }
  /* The art drifts down at 0.3 x the scroll and grows by 0.01 % per px (HomeHeroSection.kt), where
     the engine has scroll timelines. */
  @supports (animation-timeline: scroll()) {
    @media (prefers-reduced-motion: no-preference) {
      [data-slot="home.hero"] [data-part="onyx.hero-art"] { animation: onyx-home-parallax linear both; animation-timeline: scroll(root block); animation-range: 0px 1000px; }
    }
  }
  /* Nuvio's overlay is the two layers below only: no left-edge darkening, no extra bottom fade. */
  [data-part="onyx.hero"]::after { content: none !important; }
  [data-part="onyx.hero"]::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background-image: linear-gradient(to top, #0d0d0d 0px, rgba(13, 13, 13, 0) 220px), linear-gradient(to bottom, rgba(13, 13, 13, 0.02) 0%, rgba(13, 13, 13, 0.12) 33.3%, rgba(13, 13, 13, 0.34) 66.7%, rgba(13, 13, 13, 0.78) 100%);
  }
  /* Content column: centred, 24 px sides; 16 px under it, plus 8 + 12 for the markers. */
  [data-part="onyx.info"] { padding: 0 24px 36px !important; gap: 0 !important; }
  [data-part="onyx.logo"] { width: 62%; max-width: none !important; aspect-ratio: 2.6; }
  [data-part="onyx.logo"] img { width: 100%; height: 100%; max-height: none; object-fit: contain; object-position: center bottom; }
  [data-part="onyx.title"] { font-family: var(--font-display); font-size: 36px !important; line-height: 44px; font-weight: 900 !important; letter-spacing: 0; text-align: center; text-shadow: none !important; }
  [data-part="onyx.meta"] { margin-top: 12px; gap: 8px !important; }
  [data-part="onyx.meta"] > * { font-family: var(--ui-font); font-size: 14px !important; line-height: 16.4px !important; font-weight: 600 !important; letter-spacing: 0; color: #f5f7f8 !important; }
  [data-part="onyx.meta"] > [data-part="onyx.dot"] { flex: none; width: 4px; height: 4px; border-radius: 999px; background: rgba(245, 247, 248, 0.7); font-size: 0 !important; line-height: 0 !important; overflow: hidden; color: transparent !important; }
  [data-part="onyx.details"] { margin-top: 14px; height: 42.7px; min-height: 0 !important; padding: 0 28px !important; border-radius: 40px !important; font-family: var(--ui-font); font-size: 16px !important; line-height: 18.7px; font-weight: 700 !important; letter-spacing: 0; }
  [data-slot="home.hero"] [data-part="hero.indicator"] { left: 0 !important; right: 0 !important; bottom: 16px !important; gap: 8px !important; justify-content: center; }
  [data-slot="home.hero"] [data-part="hero.dot"] { padding: 0 !important; }
  /* Nuvio's dot alpha sits in a layer after the fill, so on screen every marker is the solid text colour. */
  [data-slot="home.hero"] [data-part="hero.dot.track"], [data-slot="home.hero"] [data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { background: #f5f7f8 !important; }
  /* Loading (HomeSkeletonLoading.kt HomeSkeletonHero): the placeholder takes the hero's own box (the
     rules above size it) and is white at 6 % under the hero's two overlays, so it fades into the page
     with no visible corner. Centred on it: a 62 % x 32 logo bar (r8), +12 a 156 x 10 bar, +14 a
     160 x 48 pill, then 12 + 8 + 16 to the bottom. The shimmer sweeps every 2.4 s. */
  [data-slot="home.hero"][data-state="loading"] { background: #0d0d0d !important; }
  [data-slot="home.hero"][data-state="loading"] > .skeloader { position: absolute !important; inset: 0; background: rgba(255, 255, 255, 0.06) !important; }
  [data-slot="home.hero"][data-state="loading"] > .skeloader::before { animation-duration: 2.4s; }
  [data-slot="home.hero"][data-state="loading"]::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background-image: linear-gradient(to top, #0d0d0d 0px, rgba(13, 13, 13, 0) 220px), linear-gradient(to bottom, rgba(13, 13, 13, 0.02) 0%, rgba(13, 13, 13, 0.12) 33.3%, rgba(13, 13, 13, 0.34) 66.7%, rgba(13, 13, 13, 0.78) 100%);
  }
  [data-slot="home.hero"][data-state="loading"]::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background: rgba(255, 255, 255, 0.06);
    -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%278%27%2F%3E%3C%2Fsvg%3E), url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%275%27%2F%3E%3C%2Fsvg%3E), url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%2724%27%2F%3E%3C%2Fsvg%3E);
    mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%278%27%2F%3E%3C%2Fsvg%3E), url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%275%27%2F%3E%3C%2Fsvg%3E), url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20width%3D%27100%25%27%20height%3D%27100%25%27%20rx%3D%2724%27%2F%3E%3C%2Fsvg%3E);
    -webkit-mask-size: 62% 32px, 156px 10px, 160px 48px;
    mask-size: 62% 32px, 156px 10px, 160px 48px;
    -webkit-mask-position: 50% calc(100% - 120px), 50% calc(100% - 98px), 50% calc(100% - 36px);
    mask-position: 50% calc(100% - 120px), 50% calc(100% - 98px), 50% calc(100% - 36px);
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
  }

  /* Sections: 12 px after the banner, 24 px between rows (12 + 12 in Nuvio's list). The last row
     keeps 12 of its 24 px, then the page's 90 px bar clearance: Nuvio's 12 + 72 + 18. */
  [data-slot="home"] { padding-bottom: 0 !important; }
  [data-slot="home.main"] { padding-top: 0 !important; margin-top: 0 !important; margin-bottom: -12px !important; }
  [data-slot="row"] [data-part="row.header"] { height: 32px; min-height: 0; margin: 0 0 10px !important; padding: 0 16px !important; align-items: center; gap: 12px; }
  [data-slot="row"][data-role="continue"] [data-part="row.header"] { height: 40px; }
  [data-part="row.title"] { font-family: var(--font-heading); font-size: 18px !important; line-height: 21px !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: none !important; color: #f5f7f8 !important; }
  [data-part="row.more"] { flex: none; display: inline-flex; width: 32px; height: 32px; margin: 0 0 0 auto !important; padding: 0 !important; gap: 0 !important; border-radius: 16px; background: #1a1a1a; color: #969ca3 !important; font-size: 0 !important; justify-content: center; align-items: center; }
  [data-part="row.more"] svg { width: 16px; height: 16px; flex: none; }
  [data-part="row.track"] { padding: 0 16px !important; scroll-padding-inline: 16px; overflow-y: hidden; scrollbar-width: none; }

  /* Poster: 126 x 186.7 (0.675), radius 12; +6 the title (14, regular), +6 the year (11, medium, muted). */
  [data-part="onyx.poster"] { gap: 6px !important; }
  [data-part="onyx.poster-art"] { aspect-ratio: 27 / 40 !important; border-radius: 12px !important; background: #1a1a1a; }
  [data-part="onyx.poster-title"] { font-family: var(--ui-font); font-size: 14px !important; line-height: 16.4px !important; font-weight: 400 !important; letter-spacing: 0; color: #f5f7f8 !important; }
  [data-part="onyx.poster-year"] { font-family: var(--font-display); font-size: 11px !important; line-height: 16px !important; font-weight: 500 !important; letter-spacing: 0.5px; color: #969ca3 !important; }

  /* Loading rows (HomeSkeletonLoading.kt, `row.skeleton`): a 126 x 189 block over 82 % x 16 and
     46 % x 12 label bars, white at 6 %; a Continue Watching placeholder is the 247 px card. */
  [data-slot="row"]:not([data-role="continue"]) [data-part="row.skeleton"] { flex: 0 0 126px; width: 126px !important; height: 229px !important; aspect-ratio: auto !important; border-radius: 0 !important; background: rgba(255, 255, 255, 0.06) !important; -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27126%27%20height%3D%27229%27%3E%3Crect%20width%3D%27126%27%20height%3D%27189%27%20rx%3D%2712%27%2F%3E%3Crect%20y%3D%27195%27%20width%3D%27103.32%27%20height%3D%2716%27%20rx%3D%276%27%2F%3E%3Crect%20y%3D%27217%27%20width%3D%2757.96%27%20height%3D%2712%27%20rx%3D%276%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27126%27%20height%3D%27229%27%3E%3Crect%20width%3D%27126%27%20height%3D%27189%27%20rx%3D%2712%27%2F%3E%3Crect%20y%3D%27195%27%20width%3D%27103.32%27%20height%3D%2716%27%20rx%3D%276%27%2F%3E%3Crect%20y%3D%27217%27%20width%3D%2757.96%27%20height%3D%2712%27%20rx%3D%276%27%2F%3E%3C%2Fsvg%3E); -webkit-mask-size: 126px 229px; mask-size: 126px 229px; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; }
  [data-slot="row"][data-role="continue"] [data-part="row.skeleton"] { flex: 0 0 247px; width: 247px !important; height: auto !important; aspect-ratio: 1.77 !important; border-radius: 12px !important; background: rgba(255, 255, 255, 0.06) !important; }

  /* Continue Watching (Card style): 247 x 139.8, radius 12, a scrim from 45 % down, the time-left
     badge top-end, code / title / episode bottom-start, a 3 px progress line inset 9. */
  [data-part="onyx.cw"] { width: 100%; height: auto !important; aspect-ratio: 1.77; border-radius: 12px !important; overflow: hidden; background: #222222; }
  [data-part="onyx.cw"]::after { content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background-image: linear-gradient(to bottom, rgba(13, 13, 13, 0) 45%, rgba(13, 13, 13, 0.7) 78%, rgba(13, 13, 13, 0.95) 100%); }
  [data-part="onyx.cw-badge"] { z-index: 2; margin: 7px !important; padding: 3px 7px !important; border-radius: 4px; background: rgba(13, 13, 13, 0.8); font-family: var(--font-display); font-size: 10px !important; line-height: 16px !important; font-weight: 600 !important; letter-spacing: 0.5px; color: #fff !important; }
  [data-part="onyx.cw-info"] { z-index: 2; box-sizing: border-box; min-width: 0; max-width: 100%; padding: 10px !important; gap: 2px !important; }
  [data-part="onyx.cw-info"] > * { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  [data-part="onyx.cw-code"] { font-family: var(--ui-font); font-size: 10px !important; line-height: 11.7px !important; font-weight: 600 !important; letter-spacing: 0.8px; }
  [data-part="onyx.cw-title"] { font-family: var(--font-display); font-size: 14px !important; line-height: 20px !important; font-weight: 600 !important; letter-spacing: 0.1px; }
  [data-part="onyx.cw-ep"] { font-family: var(--font-display); font-size: 10px !important; line-height: 16px !important; font-weight: 500 !important; letter-spacing: 0.4px; color: rgba(245, 247, 248, 0.72) !important; }
  [data-part="onyx.cw"] [data-part="onyx.cw-progress"] { position: absolute; z-index: 2; left: 9px; right: 9px; bottom: 4px; width: auto !important; height: 3px !important; min-height: 0 !important; margin: 0 !important; border-radius: 999px; background: rgba(0, 0, 0, 0.3) !important; overflow: hidden; }
  [data-part="onyx.cw"] [data-part="onyx.cw-progress"] > span { background: #f5f5f5 !important; border-radius: 999px; }
  /* Looking up the source: the card dims under a plain white spinner. */
  [data-part="card"][data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] { border-radius: 12px; background: rgba(13, 13, 13, 0.55); }
  [data-part="card"][data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] > span { width: 40px; height: 40px; background: transparent !important; color: #f5f5f5 !important; }
  [data-part="card"][data-family="continue"] > [data-part="card.overlay"][data-state="resolving"] svg { width: 36px; height: 36px; }

  /* Search (SearchScreen.kt, DropdownChip.kt, PosterGrid.kt): the page's own heading (`search.title`,
     in the app language) shown as the 38 px page title; a 56 px field (#222, 1 px outline, 2 px white
     while focused); the filters as 12 px dropdown chips; a three-column grid 12 px apart. Title and
     field are Nuvio's sticky header: at rest the title sits 10 px + the status bar lower than when
     pinned (the list's top padding scrolls away first), so both pin 10 px + the status bar higher. */
  [data-slot="search"] [data-part="search.title"] { position: sticky; top: calc(-10px - env(safe-area-inset-top, 0px)); z-index: 6; width: auto; height: auto; margin: calc(-16px - env(safe-area-inset-top, 0px)) -16px -70px; padding: calc(env(safe-area-inset-top, 0px) * 2 + 10px) 16px 80px; overflow: visible; clip: auto; white-space: normal; background: #0d0d0d; font-family: var(--ui-font); font-size: 38px; line-height: 42px; font-weight: 700; letter-spacing: -1.2px; color: #f5f7f8; }
  [data-slot="search"] [data-part="search.filters"] { display: contents; }
  /* The pinned title reads "Discover" once the Discover heading is the list's first item (Nuvio's
     discoverInFocus, firstVisibleItemIndex > 0): after the header's 146 px + the 12 px list gap. */
  @supports (animation-timeline: scroll()) {
    [data-slot="search"]:has([data-part="search.field"]:placeholder-shown) [data-part="search.title"]:not([data-variant="explore"]) { animation: onyx-title-off linear both; animation-timeline: scroll(root block); animation-range: 157px 159px; }
    [data-slot="search"]:has([data-part="search.field"]:placeholder-shown) [data-part="search.title"]:not([data-variant="explore"])::after { content: "Discover"; position: absolute; left: 16px; top: calc(env(safe-area-inset-top, 0px) * 2 + 10px); color: #f5f7f8; animation: onyx-title-on linear both; animation-timeline: scroll(root block); animation-range: 157px 159px; }
  }
  [data-slot="search"] [data-part="search.field"] { position: sticky; top: calc(env(safe-area-inset-top, 0px) + 52px); z-index: 7; margin-bottom: 14px; box-sizing: border-box; height: 56px; padding: 0 16px; border: 1px solid #252a2a; border-radius: 12px; background: #222222; font-family: var(--ui-font); font-size: 15px; line-height: 22px; color: #f5f7f8; outline: none; box-shadow: none; }
  [data-slot="search"] [data-part="search.field"]:focus { border: 2px solid #f5f5f5; padding: 0 15px; }
  [data-slot="search"] [data-part="search.field"]::placeholder { color: #969ca3; opacity: 1; }
  [data-slot="search"] [data-part="search.filter"] { min-height: 0; padding: 8px 12px !important; gap: 6px !important; border: 0 !important; border-radius: 12px !important; background-color: #1a1a1a !important; font-family: var(--ui-font); font-size: 14px !important; line-height: 16.4px; font-weight: 600 !important; color: #f5f7f8 !important; }
  [data-slot="search"] [data-part="search.filter"] > span { color: #f5f7f8 !important; }
  [data-slot="search"] [data-part="search.filter"] svg { width: 18px; height: 18px; color: #969ca3 !important; }
  /* The Season, Year and Sort filters are <select>s, whose line height Chromium keeps "normal": the
     same fixed 34 px as the button chips. */
  [data-slot="search"] select[data-part="search.filter"] { box-sizing: border-box; height: 34px; }
  [data-slot="search"] [data-part="search.grid"] { column-gap: 12px !important; row-gap: 12px !important; }
  /* With an empty field the content opens with Nuvio's "Discover" heading (SearchDiscoverContent.kt,
     displaySmall: Roboto 36 / 44), 12 px under the pinned header and 12 px above the dropdown chips.
     The page is a column, so the heading (the filters' own ::after: the filters box is display:
     contents) is ordered with the title and the field, ahead of the chips. */
  [data-slot="search"]:has(> [data-slot="search.header"] [data-part="search.filters"]) { display: flex; flex-direction: column; }
  [data-slot="search"] > [data-slot="search.header"] :is([data-part="search.title"], [data-part="search.field"]) { order: -1; }
  [data-slot="search"]:has([data-part="search.field"]:placeholder-shown):not(:has([data-part="search.title"][data-variant="explore"])) > [data-slot="search.header"] [data-part="search.filters"]::after { content: "Discover"; order: -1; margin: 12px 0; font-family: var(--font-display); font-size: 36px; line-height: 44px; font-weight: 400; letter-spacing: 0; color: #f5f7f8; }
  [data-part="onyx.tile"] { gap: 8px !important; }
  [data-part="onyx.tile-art"] { aspect-ratio: 17 / 25 !important; border-radius: 12px !important; background: #1a1a1a; }
  [data-part="onyx.tile-title"] { font-family: var(--ui-font); font-size: 16px !important; line-height: 20px !important; font-weight: 600 !important; letter-spacing: 0; color: #f5f7f8 !important; }
  [data-part="onyx.tile-year"] { font-family: var(--ui-font); font-size: 14px !important; line-height: 16.4px !important; font-weight: 400 !important; letter-spacing: 0; color: #969ca3 !important; }

  /* Bottom bar: a floating glass stadium, 28 px from the sides and 14 px above the inset, 64 tall;
     each tab a quarter of the inner width with a 56 px tinted pill behind the current one. */
  [data-slot="nav.bottom"] {
    left: 28px !important;
    right: 28px !important;
    max-width: 400px;
    margin-inline: auto;
    bottom: calc(14px + env(safe-area-inset-bottom, 0px)) !important;
    box-sizing: border-box;
    height: 64px;
    padding: 4px !important;
    gap: 0 !important;
    align-items: stretch;
    border: 0 !important;
    border-radius: 999px !important;
    background: rgba(28, 28, 30, 0.55) !important;
    -webkit-backdrop-filter: blur(24px);
    backdrop-filter: blur(24px);
