  [data-slot="nav.bottom"] [data-part="nav.item"][data-dest="home"] [data-part="nav.item.icon"] { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M10%2020v-6h4v6h5v-8h3L12%203%202%2012h3v8z%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M10%2020v-6h4v6h5v-8h3L12%203%202%2012h3v8z%27%2F%3E%3C%2Fsvg%3E); }
