  [data-slot="nav.bottom"] [data-part="nav.item"][data-dest="library"] [data-part="nav.item.icon"] { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M6.4%202.85h11.2%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%271.7%27%20stroke-linecap%3D%27round%27%2F%3E%3Cpath%20d%3D%27M4.4%205.7h15.2%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%2F%3E%3Cpath%20fill-rule%3D%27evenodd%27%20d%3D%27M4.2%207.6H19.8Q22%207.6%2021.8%209.8L20.6%2019.8Q20.4%2022%2018.2%2022H5.8Q3.6%2022%203.4%2019.8L2.2%209.8Q2%207.6%204.2%207.6ZM8.75%2017.25h6.5a.75.75%200%200%201%200%201.5h-6.5a.75.75%200%200%201%200-1.5Z%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M6.4%202.85h11.2%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%271.7%27%20stroke-linecap%3D%27round%27%2F%3E%3Cpath%20d%3D%27M4.4%205.7h15.2%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%2F%3E%3Cpath%20fill-rule%3D%27evenodd%27%20d%3D%27M4.2%207.6H19.8Q22%207.6%2021.8%209.8L20.6%2019.8Q20.4%2022%2018.2%2022H5.8Q3.6%2022%203.4%2019.8L2.2%209.8Q2%207.6%204.2%207.6ZM8.75%2017.25h6.5a.75.75%200%200%201%200%201.5h-6.5a.75.75%200%200%201%200-1.5Z%27%2F%3E%3C%2Fsvg%3E); }
  [data-slot="nav.bottom"] [data-part="nav.item"][data-dest="settings"] [data-part="nav.item.icon"] { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M12%202C6.48%202%202%206.48%202%2012s4.48%2010%2010%2010%2010-4.48%2010-10S17.52%202%2012%202zm0%204c1.93%200%203.5%201.57%203.5%203.5S13.93%2013%2012%2013s-3.5-1.57-3.5-3.5S10.07%206%2012%206zm0%2014c-2.03%200-4.43-.82-6.14-2.88C7.55%2015.8%209.68%2015%2012%2015s4.45.8%206.14%202.12C16.43%2019.18%2014.03%2020%2012%2020z%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M12%202C6.48%202%202%206.48%202%2012s4.48%2010%2010%2010%2010-4.48%2010-10S17.52%202%2012%202zm0%204c1.93%200%203.5%201.57%203.5%203.5S13.93%2013%2012%2013s-3.5-1.57-3.5-3.5S10.07%206%2012%206zm0%2014c-2.03%200-4.43-.82-6.14-2.88C7.55%2015.8%209.68%2015%2012%2015s4.45.8%206.14%202.12C16.43%2019.18%2014.03%2020%2012%2020z%27%2F%3E%3C%2Fsvg%3E); }
