/* ── Phone cards: the watched badge over a completed series' poster (a 20 px #F5F5F5 circle, a 12 px
   #111 tick, 6 px from the top-end corner), on Home shelves, the series page's shelves and search. ── */
@media (max-width: 640px) {
  [data-part="onyx.watched"] {
    display: block;
    width: 20px;
    height: 20px;
    margin: 6px;
    border-radius: 999px;
    background: #f5f5f5;
    font-size: 0;
    line-height: 0;
  }
  [data-part="onyx.watched"]::after {
    content: "";
    display: block;
    width: 12px;
    height: 12px;
    margin: 4px;
    background: #111111;
    -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M9%2016.17%204.83%2012l-1.42%201.41L9%2019%2021%207l-1.41-1.41z%27%2F%3E%3C%2Fsvg%3E) center / 100% 100% no-repeat;
    mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M9%2016.17%204.83%2012l-1.42%201.41L9%2019%2021%207l-1.41-1.41z%27%2F%3E%3C%2Fsvg%3E) center / 100% 100% no-repeat;
  }
}

/* ── Phone Library (LibraryScreen.kt, LibrarySavedContent.kt, DropdownChip.kt): a 38 / 42 page title
   with the services button at its end, the library sections as Nuvio's stadium source chips (r18,
   14 / 8 padding, 12 / 14 text: the current one #303030 with a 1 px white 45 % rule), the list and
   order as dropdown chips, and the three-column poster grid of Nuvio's grid layout (titles under
   the posters). ── */
@media (max-width: 640px) {
  /* The title and the chips are Nuvio's sticky header (NuvioScreenHeader + LibrarySourceSwitch): at
     rest 10 px under the status bar's own padding (the list's top padding), pinned at the very top
     once that has scrolled away; the status bar's height, a 48 px row with the title on its bottom
     edge and the 48 px button at its end (16 from the edge), 4, the chips, 6. */
  [data-part="library.tabs"] { position: sticky; top: 0; z-index: 6; flex-wrap: wrap; align-items: center; column-gap: 8px !important; row-gap: 4px !important; margin-top: 10px; padding: env(safe-area-inset-top, 0px) 16px 6px !important; border-bottom: 0 !important; background: #0d0d0d; }
  [data-part="library.tabs"]::before { content: "Library"; flex: 1 0 calc(100% - 56px); align-self: flex-end; margin: 0; font-family: var(--ui-font); font-size: 38px; line-height: 42px; font-weight: 700; letter-spacing: -1.2px; color: #f5f7f8; }
  [data-part="library.tabs"] > [data-page-tabs-skip] { order: 1; width: 48px; min-width: 0 !important; height: 48px; min-height: 0 !important; margin: 0 0 0 auto !important; color: #969ca3 !important; }
  [data-part="library.tabs"] > [data-page-tabs-skip] svg { width: 24px; height: 24px; }
  [data-part="library.tabs"] > a:not([data-page-tabs-skip]) { order: 2; box-sizing: border-box; height: 30px; min-height: 0 !important; padding: 0 14px; gap: 6px !important; border: 1px solid transparent !important; border-radius: 18px; background: #1d1b20; font-family: var(--ui-font); font-size: 12px !important; line-height: 14px; font-weight: 400 !important; letter-spacing: 0.8px; color: #969ca3 !important; }
  [data-part="library.tabs"] > a[aria-current="page"] { border-color: rgba(245, 245, 245, 0.45) !important; background: #303030; font-weight: 600 !important; color: #f5f7f8 !important; }
  /* The page's own heading and blurb give way to the title above. */
  [data-slot="library"] { padding-top: 12px !important; }
  [data-slot="library"] > header { display: none; }
  /* The list picker: a dropdown chip (r12, #1A1A1A, 8 / 12 padding, 14 / 600, an 18 px #969CA3 chevron); list management sits at the end of the row. */
  [data-slot="library"] > div:first-of-type { margin-bottom: 12px !important; }
  [data-slot="library"] > div:first-of-type > div > span:first-child { display: none; }
  [data-slot="library"] > div:first-of-type > div > div { width: auto !important; }
  [data-slot="library"] > div:first-of-type > div > div > button { min-height: 0 !important; height: 34px; padding: 0 12px !important; gap: 6px !important; border-radius: 12px !important; background: #1a1a1a !important; font-family: var(--ui-font); font-size: 14px !important; line-height: 16.4px; font-weight: 600 !important; color: #f5f7f8 !important; }
  [data-slot="library"] > div:first-of-type > div > div > button svg { width: 18px; height: 18px; color: #969ca3; }
  [data-slot="library"] > div:first-of-type > button { width: 36px !important; height: 36px !important; margin-left: auto; border-radius: 999px !important; background: transparent !important; color: #969ca3; }
  [data-slot="library"] > div:first-of-type > button svg { width: 22px; height: 22px; }
  /* Filter, order and layout: a 40 px field like Search's, the order as a dropdown chip, the layout toggle as bare icons. */
  [data-slot="library"] div:has(> label > input) { gap: 8px !important; margin-bottom: 12px !important; }
  [data-slot="library"] label > input { box-sizing: border-box; height: 40px !important; border: 1px solid #252a2a; border-radius: 12px !important; background: #222222 !important; font-family: var(--ui-font); font-size: 15px !important; color: #f5f7f8; }
  [data-slot="library"] label > input::placeholder { color: #969ca3; opacity: 1; }
  [data-slot="library"] div:has(> label > input) > select { height: 34px !important; padding: 0 8px 0 12px !important; border-radius: 12px !important; background-color: #1a1a1a !important; font-family: var(--ui-font); font-size: 14px !important; font-weight: 600 !important; color: #f5f7f8; }
  [data-slot="library"] div:has(> label > input) > [role="group"] { height: 36px !important; padding: 0 !important; gap: 0; border-radius: 999px !important; background: transparent !important; }
  [data-slot="library"] div:has(> label > input) > [role="group"] > button { width: 36px !important; border-radius: 999px !important; color: #969ca3; }
  [data-slot="library"] div:has(> label > input) > [role="group"] > button[aria-pressed="true"] { background: rgba(245, 245, 245, 0.15) !important; color: #f5f7f8 !important; }
  [data-slot="library"] > div:has(> .skeloader) { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 12px !important; }
  [data-slot="library"] > div:has(> .skeloader) > .skeloader { border-radius: 12px !important; background: rgba(255, 255, 255, 0.06) !important; }
  /* The grid: three columns 12 px apart; posters 2 : 3, radius 12; title (16 / 20, 600, two lines) and progress under each. */
  [data-slot="library.grid"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 12px !important; }
  [data-slot="library.grid"] > div > a { padding-bottom: 66px; }
  [data-slot="library.grid"] > div > a > div { overflow: visible !important; border-radius: 12px !important; background: transparent !important; }
  [data-slot="library.grid"] > div > a > div > img { border-radius: 12px; background: #1a1a1a; transform: none !important; }
  [data-slot="library.grid"] > div > a > div > span { top: 7px !important; left: 7px !important; padding: 3px 7px !important; border-radius: 4px !important; background: rgba(13, 13, 13, 0.8) !important; box-shadow: none !important; font-family: var(--font-display); font-size: 10px !important; line-height: 16px !important; font-weight: 600 !important; letter-spacing: 0.5px !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child { top: calc(100% + 8px); bottom: auto !important; padding: 0 !important; background: none !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child > p { font-family: var(--ui-font); font-size: 16px !important; line-height: 20px !important; font-weight: 600 !important; color: #f5f7f8 !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child > div { margin-top: 6px !important; gap: 6px !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child > div > div { height: 3px !important; background: rgba(245, 247, 248, 0.12) !important; box-shadow: none !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child > div > div > div { background: #f5f5f5 !important; }
  [data-slot="library.grid"] > div > a > div > div:last-child > div > span { font-family: var(--ui-font); font-size: 12px !important; font-weight: 400 !important; color: #969ca3 !important; }
  /* izumi's quick Play / +1 sit in the poster's bottom-end corner, clear of the new-episodes badge. */
  [data-slot="library.grid"] > div > div { top: auto !important; bottom: 72px !important; right: 6px !important; gap: 4px !important; }
  [data-slot="library.grid"] > div > div > button { width: 30px !important; height: 30px !important; background: rgba(13, 13, 13, 0.8) !important; box-shadow: none !important; }
}

/* ── Series page, shared and desktop: Nuvio MetaDetailsScreen ── */
/* No poster card: the title (the title logo with `detail.title: "logo"`) heads the page. */
[data-slot="detail"] [data-part="detail.poster"],
[data-slot="detail"] [data-part="detail.alt-title"] { display: none; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 40px; background: #f5f7f8; color: #0d0d0d; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] svg { fill: currentColor; }

/* Stacked sections (`detail.sections.mode: "stack"`): 20 / 600 titles, 20 px between sections. */
[data-slot="detail.section"] { margin-top: 20px; }
[data-slot="detail.section"]:first-of-type { margin-top: 0; }
[data-part="detail.section-title"] {
  margin-bottom: 14px;
  font-family: var(--font-heading);
  font-size: 20px;
  line-height: 24px;
  font-weight: 600;
  color: #f5f7f8;
}
[data-slot="detail"] [data-part="detail.meta"] {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  color: #f5f7f8;
}
[data-part="detail.airing"] { display: none; }
[data-slot="detail"] [data-part="detail.synopsis"] { color: #f5f7f8; font-size: 14px; line-height: 22px; }

/* Desktop Overview facts: Nuvio's Show Details rows (right-aligned values, a hairline rule). */
[data-slot="detail.section"][data-section="overview"] [data-part="fact"] {
  border-radius: 0;
  background: transparent;
  padding: 10px 0;
  border-bottom: 1px solid rgba(245, 247, 248, 0.1);
}
[data-slot="detail.section"][data-section="overview"] [data-part="fact.label"] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
  color: rgba(245, 247, 248, 0.8);
}
[data-slot="detail.section"][data-section="overview"] [data-part="fact.value"] {
  margin-top: 2px;
  font-weight: 500;
  color: #f5f7f8;
}

/* Desktop cast: circular avatars with a name/role caption. */
[data-section="characters"] [data-part="person"] {
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  text-align: center;
}
[data-section="characters"] [data-part="person.photo"] {
  width: 80px;
  height: 80px;
  aspect-ratio: 1 / 1;
  border-radius: 999px;
  object-fit: cover;
}
[data-section="characters"] [data-part="person.name"] { font-size: 14px; font-weight: 700; color: #f5f7f8; }
[data-section="characters"] [data-part="person.role"] { font-size: 12px; color: #969ca3; text-transform: capitalize; }

/* Season picker (`detail.episodes.seasons: "posters"`): 100 x 150 covers, radius 8, a 1 px / 2 px
   ring. On desktop the "Seasons" heading is reserved as top padding on the picker itself. */
[data-slot="episodes.seasons"][data-variant="posters"] { padding-top: 30px; gap: 16px; }
[data-slot="episodes.seasons"][data-variant="posters"]::before {
  content: "Seasons";
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-heading);
  font-size: 18px;
  line-height: 24px;
  font-weight: 600;
  color: #f5f7f8;
}
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"] { width: 100px; }
/* The cover is the <img> itself, so the ring is an outline (drawn over the picture, inside the radius). */
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season.art"] {
  border-radius: 8px;
  background: rgba(34, 34, 34, 0.5);
  outline: 1px solid rgba(255, 255, 255, 0.1);
  outline-offset: -1px;
}
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"][data-active] [data-part="season.art"] { outline: 2px solid #f5f5f5; outline-offset: -2px; }
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season.label"] { font-size: 15px; font-weight: 600; color: #969ca3; }
[data-slot="episodes.seasons"][data-variant="posters"] [data-part="season"][data-active] [data-part="season.label"] { font-weight: 700; color: #f5f7f8; }

/* Episode toolbar: `controls: []` and `order: "none"` leave only the small overflow button. */
