[data-slot="detail"][data-variant="phone"]:not([data-pending]) > :not([data-slot="detail.bar"]) { animation: onyx-page-in 220ms cubic-bezier(0.2, 0, 0, 1); }

/* Hero: 1.33 x the width (420-760), the art sharp and 1.08 x, a 7-stop fade 320 px up from the
   bottom. The art is Nuvio's `background ?: poster`: key art, else the full-resolution portrait
   poster, else the cover itself (`detail.art: "portrait"`, `artFallback: "cover"`), never the
   stretched wide banner or a colour wash. While the choice is pending the band stays the page colour. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] {
  height: clamp(420px, 133vw, 760px) !important;
  min-height: 0 !important;
  max-height: none !important;
  background-color: #0d0d0d;
  background-image: none !important;
}
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"][data-art="pending"] > :not([data-part]) { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.backdrop"] { transform: scale(1.08); object-position: center !important; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.banner.fade"] {
  top: auto !important;
  height: 320px !important;
  pointer-events: none;
  background-image: linear-gradient(to bottom, rgba(13, 13, 13, 0) 0%, rgba(13, 13, 13, 0.04) 16%, rgba(13, 13, 13, 0.14) 32%, rgba(13, 13, 13, 0.34) 50%, rgba(13, 13, 13, 0.62) 68%, rgba(13, 13, 13, 0.84) 84%, #0d0d0d 100%) !important;
}
/* The hero's last device pixel: the drifting art is a layer of its own, clipped on a whole pixel,
   while the fade above it ends part-way through that pixel, so a light line of art showed through.
   A 4 px strip of the page colour over the hero's last 3 px and the first 1 px under it closes it;
   Play and the circles sit above the strip. */
[data-slot="detail"][data-variant="phone"]::before {
  content: "";
  position: absolute;
  z-index: 1;
  left: 0;
  right: 0;
  top: calc(clamp(420px, 133vw, 760px) - 3px);
  height: 4px;
  background: #0d0d0d;
  pointer-events: none;
}
/* The art drifts at half the scroll speed (DetailHero.kt parallax 0.5), where the engine has scroll timelines. */
@supports (animation-timeline: scroll()) {
  @media (prefers-reduced-motion: no-preference) {
    [data-slot="detail"][data-variant="phone"] [data-part="detail.backdrop"] {
      animation: onyx-parallax linear both;
      animation-timeline: scroll(root block);
      animation-range: 0px 1000px;
    }
  }
}

/* The page column: Nuvio's 18 px sections (MetaDetailsScreen.kt). */
[data-slot="detail"][data-variant="phone"] [data-part="detail.content"] { padding-inline: 18px !important; }
