   movie label, "Play" / "Resume", naming the episode only past the first ("Resume E5"). */
[data-slot="detail"][data-variant="phone"] [data-part="detail.buttons"] > [data-action="play"][data-episode] { font-size: 0; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.buttons"] > [data-action="play"][data-episode]::after { content: "Play"; font-size: 14px; }
