[data-slot="detail"][data-variant="phone"] [data-part="detail.buttons"] > [data-action="play"] svg { flex: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.buttons"] > [data-action="play"][data-episode]::after { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] { width: max-content; margin: -52px 0 0 auto; gap: 12px; }
