}
[data-slot="detail"][data-variant="phone"]:has([data-part="detail.actions"][data-expanded]) [data-part="detail.buttons"] > [data-part="detail.list-button"][data-state="listed"] { background: #f5f7f8; color: #0d0d0d; }
