  -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M19%2013h-6v6h-2v-6H5v-2h6V5h2v6h6v2z%27%2F%3E%3C%2Fsvg%3E) center / 100% 100% no-repeat;
