/* The list button and tracker links behind "…" drop down as Nuvio's own menu (Menu.kt): 6 px under
   the row, end-aligned, at least 180 wide, radius 20, #222 inside a 1 px white 16 -> 4 % rim, 8 px
   above and below the items; items 8 in and 12 padding, 15 / 22 text, no icons. No scrim. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.menu"] {
  top: calc(100% + 6px) !important;
  bottom: auto !important;
  right: 0 !important;
