   40 px box 16 px from the end, a 24 px icon): the list button, "+" to add the title to a list, a
   tick once it is on one, folded row or not (the actions row has scrolled away under the bar). */
[data-slot="detail"][data-variant="phone"]:has(> [data-slot="detail.bar"][data-solid]) [data-part="detail.buttons"] > [data-part="detail.list-button"] {
  display: flex !important;
  position: fixed !important;
  z-index: 31 !important;
  top: calc(max(calc(env(safe-area-inset-top, 0px) - 6px), calc(env(safe-area-inset-top, 0px) * 0.8)) + 4px);
  right: 12px;
  box-sizing: border-box;
  width: 48px !important;
  height: 48px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 999px;
  align-items: center;
  justify-content: center;
  background: transparent !important;
  color: #f5f7f8 !important;
  font-size: 0;
  animation: onyx-bar-in 150ms cubic-bezier(0.2, 0, 0, 1);
}
[data-slot="detail"][data-variant="phone"]:has(> [data-slot="detail.bar"][data-solid]) [data-part="detail.buttons"] > [data-part="detail.list-button"]::before { width: 24px; height: 24px; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.bar.title"] {
  margin-top: calc(max(calc(env(safe-area-inset-top, 0px) - 6px), calc(env(safe-area-inset-top, 0px) * 0.8)) + 16px);
  padding: 0 6px;
  text-align: center;
  font-family: var(--ui-font);
  font-size: 18px;
  line-height: 24px;
  font-weight: 700;
  letter-spacing: 0;
  animation: onyx-bar-in 150ms cubic-bezier(0.2, 0, 0, 1);
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.bar.title"]:has(> [data-part="detail.bar.logo"]) { margin-top: calc(max(calc(env(safe-area-inset-top, 0px) - 6px), calc(env(safe-area-inset-top, 0px) * 0.8)) + 7px); }
[data-slot="detail"][data-variant="phone"] [data-part="detail.bar.logo"] {
  display: block;
  width: min(240px, 60vw) !important;
  height: 42px !important;
  max-width: 100% !important;
  margin-inline: auto;
  object-fit: contain;
  object-position: center !important;
}

@keyframes onyx-bar-in { from { opacity: 0; transform: translateY(-20px); } }
@keyframes onyx-page-in { from { opacity: 0; } }
@keyframes onyx-menu-in { from { opacity: 0; transform: scale(0.92); } }
@keyframes onyx-circle-in { from { flex-basis: 0; width: 0; margin-left: -12px; opacity: 0; transform: scale(0.86); } }
@keyframes onyx-circle-pop { from { opacity: 0; transform: scale(0.86); } }
@keyframes onyx-title-off { to { color: transparent; } }
@keyframes onyx-title-on { from { opacity: 0; } to { opacity: 1; } }
@keyframes onyx-parallax { from { transform: translateY(0) scale(1.08); } to { transform: translateY(500px) scale(1.08); } }
/* The Home art drifts at 0.3 x the scroll and grows 0.01 % per px; its clip keeps it 2 px above the
   banner's bottom all the way (the same seam guard as the static clip), so a keyframe per quarter. */
@keyframes onyx-home-parallax {
  0% { transform: translateY(0px) scale(1); clip-path: inset(0 0 calc(6.1404% + 2.000px) 0); }
  25% { transform: translateY(75px) scale(1.025); clip-path: inset(0 0 calc(7.2101% + 75.122px) 0); }
  50% { transform: translateY(150px) scale(1.05); clip-path: inset(0 0 calc(8.2289% + 144.762px) 0); }
  75% { transform: translateY(225px) scale(1.075); clip-path: inset(0 0 calc(9.2003% + 211.163px) 0); }
  100% { transform: translateY(300px) scale(1.1); clip-path: inset(0 0 calc(10.1276% + 274.545px) 0); }
}
